package ru.samates.gardenspa.domain

/** Dates are planning checkpoints, not predictions of flowering or infection. */
object SeasonalCarePrograms {
    private const val PHASE_NOTICE = "Дата ориентировочная: сверяйтесь с фактической фазой развития, погодой и уже выполненными работами."
    private const val INSPECTION_NOTICE = "При подтверждённой болезни или вредителе откройте «После осмотра» в программе и выберите средство. Название проблемы можно пропустить. Обработка без признаков поражения автоматически не назначается."

    private fun check(id: String, title: String, day: Int, note: String) = CareStepTemplate(
        id = id, title = title, offsetDays = day, windowAfterDays = 14,
        note = "$note\n$PHASE_NOTICE\n$INSPECTION_NOTICE"
    )

    private fun program(
        id: String, name: String, aliases: Set<String>, startOffset: Int, productId: String,
        nutritionDay: Int = 0, repeat: CareRecurrence? = null, nutritionCondition: String,
        inspection: String, stages: List<CareStepTemplate>
    ): PlantCareTemplate {
        val product = SeasonalProgramProducts.products.first { it.id == productId }
        return PlantCareTemplate(
            id, name, aliases + name.lowercase(), version = 6,
            supportedCultivationTypes = setOf(CultivationType.OPEN_GROUND),
            openGroundStartOffsetDays = startOffset,
            steps = listOf(
                CareStepTemplate("nutrition~$productId", "Подкормить: $name", offsetDays = nutritionDay,
                    windowAfterDays = 14, recurrence = repeat, productDescription = product.displayName,
                    note = "$nutritionCondition\n${product.purpose}\n${product.instruction}\nИсточник: ${product.sourceUrl}\n$PHASE_NOTICE\nВыберите одно удобрение; альтернативы не вносят вместе. Учитывайте ранее внесённое питание."),
                CareStepTemplate("regular_inspection", "Осмотреть: $name", offsetDays = 7,
                    recurrence = CareRecurrence(RepeatType.CUSTOM, 14, 12),
                    note = "$inspection\n$INSPECTION_NOTICE")
            ) + stages
        )
    }

    val templates = listOf(
        program("peony", "Пион", setOf("пионы", "пион травянистый", "пион ито", "ито-пион"), -21,
            "organic_flowers", repeat = CareRecurrence(RepeatType.CUSTOM, 45, 3),
            nutritionCondition = "Начинайте питание при появлении побегов и оттаивании почвы. Для молодого саженца и взрослого куста нормы различаются.",
            inspection = "Осмотрите основания побегов, бутоны и листья: потемнение и увядание могут требовать проверки на ботритис; белый налёт — на мучнистую росу.",
            stages = listOf(
                check("buds", "Проверить бутоны пиона", 35, "Осмотрите бутоны до раскрытия. Подкормку по листу не проводить по открытым цветкам."),
                check("after_flowering", "Проверить пион после цветения", 75, "Оцените листья и основание куста. Сохраните здоровую листву; повторное питание — только с учётом выбранного удобрения."),
                check("season_end", "Осмотреть пион перед завершением сезона", 150, "Оцените пятнистости и отмирающие части. Не переносите нормы для травянистого пиона на древовидный без проверки инструкции.")
            )),
        program("hydrangea", "Гортензия", setOf("гортензии"), -7, "organic_hydrangea",
