                check("season_end", "Проверить розу перед окончанием роста", 150, "Не продолжайте подкормки по инерции; учтите период действия внесённых гранул и условия зимовки.")
            )),
        program("blackberry", "Ежевика", setOf("ежевики"), -7, "organic_berries",
