            nutritionCondition = "Вносите по началу роста в корнеобитаемый слой, не повреждая корни. Учитывайте возраст куста и уже внесённую органику.",
            inspection = "Проверьте листья, побеги и ягоды на пятнистости, серую гниль, тлю, клеща и долгоносика.",
            stages = listOf(
                check("before_flowering", "Осмотреть ежевику перед цветением", 40, "Проверьте молодые листья и бутоны. Для цветущих посадок учитывайте ограничения по опылителям."),
                check("fruiting", "Проверить ежевику при созревании ягод", 90, "Перед любой обработкой сопоставьте срок ожидания с ближайшим сбором."),
                check("after_harvest", "Проверить ежевику после сбора", 145, "У поздних сортов и ремонтантной ежевики срок сдвигается; ориентируйтесь на фактическое завершение сбора.")
