                check("fruiting", "Проверить малину перед сбором ягод", 70, "Сопоставьте срок ожидания с частотой сбора. Календарная дата не определяет спелость ягод."),
                check("after_harvest", "Осмотреть малину после плодоношения", 130, "У ремонтантной малины плодоношение может продолжаться; не считайте сбор завершённым по календарю.")
