            repeat = CareRecurrence(RepeatType.CUSTOM, 45, 3),
            nutritionCondition = "Начинайте подкормку при распускании листьев и оттаявшей почве. Для обработки проверяйте, указан ли ваш вид смородины на этикетке.",
            inspection = "Проверьте почки, верхушки побегов и листья: деформации, тля, налёт мучнистой росы и пятнистости требуют разного подбора средств.",
            stages = listOf(
                check("flowering", "Осмотреть смородину перед цветением", 21, "Проверьте молодую листву и соцветия. Учитывайте присутствие опылителей."),
                check("harvest", "Проверить смородину в период сбора", 80, "Не назначайте обработку без проверки срока ожидания."),
                check("after_harvest", "Осмотреть смородину после сбора", 110, "Оцените состояние листьев и прироста; подкормки соотнесите с ранее выбранным продуктом.")
            )),
        program("garden-strawberry", "Земляника", setOf("земляника садовая", "клубника", "клубника ремонтантная", "земляника садовая ремонтантная", "земляника садовая короткого дня", "земляника садовая нейтрального дня", "клубника одноразовая", "клубника июньская", "клубника нейтрального дня"), -14,
            "organic_berries", repeat = CareRecurrence(RepeatType.CUSTOM, 45, 3),
            nutritionCondition = "Подкормка после возобновления роста листьев. Гранулы не засыпают сердечко. Для ремонтантных сортов учитывайте непрерывный сбор.",
            inspection = "Проверьте молодые листья, бутоны и ягоды на клеща, долгоносика, пятнистости и серую гниль.",
            stages = listOf(
                check("buds", "Осмотреть бутоны земляники", 21, "Проверьте повреждённые и поникающие бутоны; подтвердите причину перед обработкой."),
                check("fruiting", "Проверить землянику во время плодоношения", 50, "Удаляйте из сбора повреждённые ягоды. Обработку выбирайте с учётом срока ожидания."),
                check("after_harvest", "Осмотреть землянику после сбора", 95, "Оцените листву и необходимость питания. У ремонтантных сортов эту проверку выполняют после фактического завершения сбора.")
            )),
        program("blueberry", "Голубика", setOf("голубика садовая", "голубика высокорослая"), -7, "organic_blueberry",
