            nutritionCondition = "Используйте питание для кислолюбивых культур по возрасту куста. Не добавляйте золу или известь как универсальную подкормку.",
            inspection = "Проверьте почву, прирост, листья и ягоды. Изменение окраски листьев может быть связано с кислотностью и питанием, а не заражением.",
            stages = listOf(
                check("flowering", "Осмотреть голубику перед цветением", 35, "Проверьте бутоны и молодые побеги; не переносите на голубику регламент препарата для смородины."),
                check("fruiting", "Проверить голубику при созревании", 90, "Для каждого выбранного средства проверьте допуск на голубику и срок ожидания."),
                check("season_end", "Оценить голубику после сбора", 135, "Проверьте созревание побегов и состояние корневой зоны; завершение питания привязывайте к условиям участка.")
            )),
        fruitTree("apple", "Яблоня", setOf("яблони", "яблоко", "яблоня на сильнорослом подвое", "яблоня на карликовом подвое", "яблоня стандартная", "яблоня семенной подвой", "яблоня карликовая", "яблоня полукарликовая")),
        fruitTree("pear", "Груша", setOf("груши", "грушевое дерево", "груша на сильнорослом подвое", "груша на слаборослом подвое", "груша на карликовом подвое", "груша стандартная", "груша карликовая", "груша полукарликовая")),
