            inspection = "Осматривайте ботву на колорадского жука и личинок, пятна фитофтороза и альтернариоза. При пятнах подтвердите причину, не выбирайте средство только по внешнему сходству.",
            stages = listOf(
                check("emergence", "Проверить картофель после всходов", 21, "Срок появления всходов зависит от почвы; сравните фактическую фазу с планом подкормки."),
                check("canopy", "Осмотреть картофель перед смыканием ботвы", 45, "Проверьте нижние листья, междурядья и присутствие жука."),
