    private fun fruitTree(id: String, name: String, aliases: Set<String>) = program(
        id, name, aliases, -21, "bona_fruit", nutritionCondition = "Подкормка при начале роста по оттаявшей почве. Норма на м² приствольного круга, а не на дерево. Повторную подкормку согласуйте с выбранным продуктом и сроком сбора.",
        inspection = "Осмотрите почки, молодые листья и плоды на паршу, налёт, тлю и повреждения плодожоркой. Для груши отдельно проверьте признаки ржавчины.",
        stages = listOf(
            check("buds", "Осмотреть бутоны: $name", 14, "В фазе зелёного конуса и обособления бутонов оцените состояние кроны. Схемы защиты привязаны к фазе, а не только к дате."),
            check("after_flowering", "Осмотреть дерево после цветения: $name", 45, "Проверьте листья и завязи. При необходимости повторного питания выберите его с учётом ранее внесённого."),
            check("fruiting", "Проверить плоды и листья: $name", 90, "Уточните ожидаемую дату сбора и срок ожидания средства перед обработкой."),
            check("after_harvest", "Осмотреть дерево после урожая: $name", 150, "У ранних и поздних сортов срок различается; ориентируйтесь на фактический сбор и состояние листвы.")
        )
